def simulate_game():
    # Cards are chosen in decreasing order: 50, 49, ..., 1
    cards = list(range(50, 0, -1))

    S1 = 0
    S2 = 0

    for k, card in enumerate(cards):
        turn = k + 1

        if turn % 2 != 0:
            # Grogg's turn (k is even, turn is odd) - Minimizer
            # Grogg minimizes |S1 - S2|. He puts the card in the currently larger pile
            # to balance the sums.
            if S1 >= S2:
                S2 += card
            else:
                S1 += card
        else:
            # Winnie's turn (k is odd, turn is even) - Maximizer
            # Winnie maximizes |S1 - S2|. She puts the card in the currently smaller pile
            # to increase the difference.
            if S1 >= S2:
                S1 += card
            else:
                S2 += card

    difference = abs(S1 - S2)
    print(difference)

simulate_game()
